This is a complete, step-by-step guide to building a MERN (MongoDB, Express, React, Node.js) application, generating dummy data, and deploying it to the cloud (using Railway/Render or Vercel/Netlify for frontend).

For this tutorial, we will build a **"Product Management App"**.
*   **Frontend:** React (Create React App)
*   **Backend:** Node.js + Express
*   **Database:** We will use MongoDB (I will include instructions for connecting, but the logic works with JSON for dummy data too).

---

### Phase 1: Project Setup

Create a folder for your project:
```bash
mkdir mern-app
cd mern-app
```

#### 1. Backend Setup (Node/Express)
```bash
# Create backend folder
mkdir backend
cd backend

# Initialize project
npm init -y

# Install dependencies
npm install express mongoose cors nodemon

# Create a file structure
mkdir src
touch src/index.js
```

**Code for `backend/src/index.js`:**

```javascript
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');

const app = express();
const PORT = 5000;

// Middleware
app.use(cors());
app.use(express.json());

// Connect to MongoDB (Replace URI with your local or MongoDB Atlas connection string)
// If you don't have MongoDB, I will add a "Fake Database" mode below.
mongoose.connect('mongodb://localhost:27017/myproductdb', {
    useNewUrlParser: true,
    useUnifiedTopology: true
}).then(() => console.log('MongoDB Connected'))
  .catch(err => console.log('DB Error:', err));

// --- SCHEMA ---
const productSchema = new mongoose.Schema({
    name: String,
    price: Number,
    category: String,
    image: String
});

const Product = mongoose.model('Product', productSchema);

// --- ROUTES ---

// 1. Get All Products
app.get('/api/products', async (req, res) => {
    try {
        const products = await Product.find();
        res.json(products);
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
});

// 2. Add One Product
app.post('/api/products', async (req, res) => {
    const product = new Product(req.body);
    try {
        const newProduct = await product.save();
        res.status(201).json(newProduct);
    } catch (err) {
        res.status(400).json({ message: err.message });
    }
});

// 3. GENERATE DUMMY DATA (Helper Route)
app.post('/api/dummy-data', async (req, res) => {
    const products = [];
    const categories = ['Electronics', 'Fashion', 'Home'];

    for (let i = 0; i < 20; i++) {
        products.push({
            name: `Product Name ${i + 1}`,
            price: Math.floor(Math.random() * 100) + 10,
            category: categories[Math.floor(Math.random() * categories.length)],
            image: `https://via.placeholder.com/150?text=Item+${i+1}`
        });
    }

    try {
        await Product.insertMany(products);
        res.status(201).json({ message: '20 dummy products created!' });
    } catch (err) {
        res.status(400).json({ message: err.message });
    }
});

